class NomTipoPartidagasto extends BaseNomTipoPartidagasto {

    /**
     * Obtener un listado de los datos de los tipos de pago.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de pago.
     */
    public static function obtenerListadoTipoPartida($inicio = 0, $limite = 10) {

        //Devolviendo el listado de tipos de partidas de pago en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTipoPartidagasto')
				->orderBy('denominacion')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }
	
	 /**
     * Obtener un listado de los datos de todos los tipos de partidas de pago.
     * 
     * @return array    Listado de los datos de los tipos de pago.
     */
    public static function obtenerTodosTipoPartidagasto() {

        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTipoPartidagasto')
				->orderBy('denominacion')
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de tipos partida de pago.
     * 
     * @return int      Cantidad total de tipos partidas de pago.
     */
    public static function obtenerCantidadTotalTipoPartida() {

        //Devolviendo la cantidad total de tipos de pago.
        return Doctrine_Query::create()->select('COUNT(idtipopartidagasto) AS cantidad')
                        ->from('NomTipoPartidagasto')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el tipo de pago dado el identificador.
     * 
     * @param int $idtipopago    Identificador del tipo de pago.
     * @return NomTipoPago      Objeto tipo de pago (clase del dominio).
     */
    public static function obtenerObjTipoPartidaPagoDadoId($idtipopartidagasto) {
        return Doctrine::getTable('NomTipoPartidagasto')->find($idtipopartidagasto);
    }
    
	
	/**
     * Obtener si existe un tipo de pago a partir de la denominaci�n.
     * 
	 * @param int $idtipop    		Identificador del tipo de pago.
     * @param string $denom    	 	Denominaci�n del tipo de pago.
	 *
     * @return boolean    			Si existe el tipo de pago.
     */
    public static function existeTipoPago($idtipopartidagasto, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idtipopartidagasto) AS cantidad')
                        ->from('NomTipoPartidagasto')
						->where("denominacion ilike ?", $denom);
		if($idtipopartidagasto){
			$query->addWhere('idtipopartidagasto <> ?', $idtipopartidagasto);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	
	
	
	
	
	
	
	
	
	
	
	
/****************************VER DESDE AQUI*************************************************************/	
    public static function existeDenominacionTipoPartida($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTipoPartidagasto p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function dameSeDesglosaDadoIdPartida($idtipopartidagasto) {
		return Doctrine_Query::create()->select('p.sedesglosa AS sedesglosa')
                        ->from('NomTipoPartidagasto p')
                        ->where('p.idtipopartidagasto = ?', array($idtipopartidagasto))
                        ->fetchOne()
                        ->sedesglosa;
   }

}
